  FROM jsonb_array_elements($j$[{"d":"2026-09-14","l":"AB","o":0,"m":1950,"e":28,"i":[["R","300 RAZP",300],["O","16x25 M 1xN 1xCT",400],["V","4x50 PL K RRU SHARK 1",200],["V","8x25 PL SCULLING",200],["M","50 RAZP",50],["G","6x50 KVL @1'\n6x25 KN p10\"\n4x50 K STOP @1'\n4x25 1x K! 1x RAZP p30\"",750],["K","50 RAZP",50]]},{"d":"2026-09-17","l":"AB","o":0,"m":2100,"e":30,"i":[["R","300 RAZP",300],["O","4x75 M VB1T",300],["V","4x50 PL KN",200],["V","4x50 PL KV 2-2",200],["M","50 RAZP",50],["G","4x50 KN @1'10\"\n4x50 K @1'\n4x50 KVL @1'\n4x50 K @55\"\n4x50 25 D + 25 RAZP @1'",1000],["K","50 RAZP",50]]},{"d":"2026-09-16","l":"C","o":0,"m":1400,"e":28,"i":[["R","200 RAZP",200],["O","4x50 PD ↑3s ↓5s",200],["V","6x25 PL KN BOK",150],["V","6x25 PL KZ 25-25",150],["V","6x25 PL K RRU",150],["V","6x25 K",150],["M","50 RAZP",50],["G","2x150 1x P 1x P/H/P",300],["K","50 RAZP",50]]},{"d":"2026-09-16","l":"A","o":0,"m":1950,"e":28,"i":[["R","300 RAZP",300],["O","6x50 ↑N ↓CT 1x H/P/K",300],["V","8x25 PL ↑PV ↓HN ROTACIJA",200],["V","4x50 PL ↑VATERPOLO ↓HN RRU 90°",200],["V","4x50 PL ↑KN MAX ↓H",200],["M","50 RAZP",50],["G","3x( 100 / 50 / 50 RAZP ) 1x VL 1x K 1x 100 M + 50 STIL",600],["K","100 RAZP",100]]},{"d":"2026-09-21","l":"AB","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","6x50 ↑K ↓H V/CT",300],["V","8x25 PL KN RV",200],["V","4x50 K RRU PESTI/PPDZ",200],["M","50 RAZP",50],["G","4x100 KVL @2'\n4x50 @1'\n4x50 25 D + 25 RAZP @1'",800],["M","100 RAZP",100],["Z","10x25 K ŠTETJE",250],["K","50 RAZP",50]]},{"d":"2026-09-24","l":"AB","o":1,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","4x100 M Z ZAMIKOM CT/N/V/CT",400],["G","3x100 VL DOLGO @2'\n3x50 VL @55\"\n3x100 PL 75 VISOK KOMOLEC DOLGO + 25 N! @2'\n3x50 PL 25 DN PV + 25 HN @1'\n3x100 T @2'\n3x50 HITRO @1'",1350],["M","50 RAZP",50],["V","6x25 POPAJ",150],["K","50 RAZP",50]]},{"d":"2026-09-23","l":"C","o":0,"m":1600,"e":32,"i":[["R","200 RAZP",200],["O","6x50 ↑P ↓H/K",300],["V","8x25 PL KN RV",200],["V","8x25 PL K 6-3-6",200]