KBD p20\"",150],["K","50 RAZP",50]]},{"d":"2026-10-08","l":"AB","o":1,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","4x100 M PO 100 CT/N/V/CT",400],["G","4x100 KVL @2'\n3x100 M @2'\n2x100 PL NOGE @2'\n1x100 HITRO @2'",1000],["M","50 RAZP",50],["V","8x25 PL K ↑BIEGNER ↓BD",200],["V","6x50 1x DN BOK 1x DV 1-1-2",300],["K","50 RAZP",50]]},{"d":"2026-10-07","l":"C","o":0,"m":1500,"e":30,"i":[["R","200 RAZP",200],["O","4x50 H/P K/P",200],["V","4x50 KN PL DESKA",200],["V","8x25 PL KZ",200],["V","10x25 K CT",250],["M","50 RAZP",50],["G","6x50 ↑HITRO ↓RAZP",300],["K","100 RAZP",100]]},{"d":"2026-10-07","l":"A","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","6x50 ↑K ↓D/H/P",300],["V","8x25 PL ↑K! ↓RAZP",200],["V","6x50 PL KV RRU 3s DN!",300],["M","50 RAZP",50],["G","6x50 25 K! BD + 25 RAZP\n6x50 K @1' BREZ VDIHA\n6x50 KVL @1'",900],["M","50 RAZP",50],["Z","6x25 PPV",150],["K","50 RAZP",50]]},{"d":"2026-10-12","l":"AB","o":1,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","8x50 MM 4xCT 4xN",400],["G","5x( 5x50 ) 3xT 1xHITRO 1xRAZP štarti CT 1'05\" N 1'20\" CT 1' N 1'15\" CT 55\"",1250,"5X(5X50) 3XT 1XHITRO 1XRAZP ŠTARTI CT @1'05\" N @1'20\" CT @1' N @1'15\" CT @55\""],["V","8x25 PL ↑D DIH NA 5 ↓K 2-2",200],["V","4x50 PL 1x PR DN 1x K RRU SHARK",200],["K","50 RAZP",50]]},{"d":"2026-10-15","l":"AB","o":0,"m":2100,"e":30,"i":[["R","300 RAZP",300],["O","6x50 H/K ↑V ↓CT",300],["V","8x25 PL DN MENJAMO POLOŽAJ",200],["V","4x50 PL 1x HV 90° 1x HV ZAVES + RAMENA",200],["M","50 RAZP",50],["G","6x25 NOGE @35\"\n6x50 KVL @1'10\"\n6x25 NOGE @30\"\n6x50 K PL @1'",900],["M","50 RAZP",50],["Z","4x25 PPV",100]]},{"d":"2026-10-14","l":"C","o":0,"m":1500,"e":30,"i":[["R","200 RAZP",200],["O","4x75 P 1-2/1-3/PD",300],["V","4x50 HN PL ROTACIJA",200],["V","8x25 PL HV ROKA VEN ZAVES",200],["V","8x25 H",200],["M","50 RAZP",50],["G","4x75 50 P + 25 K/H",300],["K","50 RAZP",50]]},{"d":"2026-10-14","l":"A","o":0,"m":2150,"e":30,"i":[["R","300 RAZP",300],["O","4x100 PL 25 CT + 75 N/V/CT",400],["V","10x25 PL ↑KN DR ↓SCULLING KN",250],["V","4x75 VL DIH 3-5-7",300],["M","50 RAZP",50],["G","5x( 100 T / 25 MAX / 25 RAZP )",750],["K","100 RAZP",100]]},{"d":"2026-10-19","l":"AB","o":1,"m":2200,"e":31,"i":[["R","300 RAZP",300],["O","6x75 MBK N/V/CT",450],["G","3x100 VL @2'\n3x50 @1'\n2x100 @2'\n2x50 @1'\n100 @2'\n50 @1'",900],["M","50 RAZP",50],["V","4x50 PL ↑KN ↓ČIM DLJE POD VODO",200],["V","10x25 PL DN PR",250],["K","50 RAZP",50]]},{"d":"2026-10-22","l":"AB","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","3x150 PL K N/V/CT",450],["V","4x50 PL SALTO NA POL",200],["V","8x25 ↑DN PV 10m + D ↓DV 2-2",200],["M","50 RAZP",50],["G","4x25 D\n4x50 @1'\n4x100 KVL @2'\n4x50 @50\"\n4x25 1x D! 1x H",1000],["K","50 RAZP",50]]},{"d":"2026-10-21","l":"C","o":0,"m":1500,"e":30,"i":[["R","200 RAZP",200],["O","4x75 50 PD 3s + 25 H",300],["V","8x25 PL KV 2-2",200],["V","8x25 PL KV RRU 3s",200],["V","4x50 1x 25 K/25 P 1x 50 K",200],["M","50 RAZP",50],["G","3x100 75 P + 25 K",300],["K","50 RAZP",50]]},{"d":"2026-10-21","l":"A","o":0,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","16x25 M 4xCT 4xN 4xCT 4xV",400],["V","2x( 8x25 ) 1x DN + SHARK 1 1x RRU PRSTI",400],["G","2x( 4x50 KVL ) 1x @1' 1x @50\"\n2x( 2x100 M ) 1x NORMALNO 1x OBRATNO\n2x200 @3'30\"",1200],["K","100 RAZP",100]]},{"d":"2026-10-26","l":"AB","o":0,"m":2350,"e":33,"i":[["R","300 RAZP",300],["O","4x100 PL 25 M + 75 H/K",400],["V","12x25 PL 3x D 1x H VSAKIČ DLJE",300],["V","4x50 L PACMAN",200],["M","50 RAZP",50],["G","3x( 5x50 @1' ) 1. VL 2. K 3. K VSAK 3. D",750],["M","50 RAZP",50],["Z","8x25 V PR",200],["K","100 RAZP",100]]},{"d":"2026-10-29","l":"AB","o":1,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","8x50 MM ↑CT ↓N",400],["G","300 VL\n200 M\n100 K HITRO\n50 NOGE\n100 K HITRO\n200 M\n300 VL",1250],["M","50 RAZP",50],["V","6x50 K PL RRU 1x SHARK 1x ZADRGA",300],["K","100 RAZP",100]]},{"d":"2026-10-28","l":"C","o":0,"m":1600,"e":32,"i":[["R","200 RAZP",200],["O","6x50 ↑P ↓H/K/GERMANJA",300],["V","8x25 PL DN H/T/B/B",200],["V","8x25 PL DV ↑LEVA ↓DESNA",200],["V","6x25 PL DV 6-1",150],["M","50 RAZP",50],["V","4x25 METULJČEK",100],["G","200 P + 100 H + 50 K",350],["K","50 RAZP",50]]},{"d":"2026-10-28","l":"A","o":0,"m":2200,"e":31,"i":[["R","300 RAZP",300],["O","4x100 M PO 25 N/CT",400],["V","8x25 PL ↑VATERPOLO ↓K ČIM DALJŠI",200],["V","4x50 PL 1x H RRU 90° 1x H 3-1",200],["M","50 RAZP",50],["G","3x( 100 K @2' / 50 K @1' )\n50 RAZP\n3x( 50 K @1' / 100 K @2' )",950],["K","100 RAZP",100]]},{"d":"2026-11-02","l":"AB","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","4x75 M VB1T",300],["V","10x25 V ML PR",250],["M","50 RAZP",50],["G","6x100 2+1 @2'",600],["M","50 RAZP",50],["V","4x50 PL KN @1'",200],["V","4x50 PL 25 DV 3-2 + 25 DN VDIH NAPREJ",200],["V","8x25 PL ↑DN PV ↓DN H",200],["K","100 RAZP",100]]},{"d":"2026-11-05","l":"AB","o":0,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","6x50 ↑N ↓V K/H",300],["V","8x25 PL KN SUPERMAN",200],["V","4x50 PL KZ DIH KONTRA",200],["M","50 RAZP",50],["G","3x( 6x50 @1' ) 1x MAD 1x VL 1x CT",900],["M","50 RAZP",50],["Z","6x50 ↑PPV ↓GERMANJA",300],["K","100 RAZP",100]]},{"d":"2026-11-04","l":"C","o":0,"m":1450,"e":29,"i":[["R","200 RAZP",200],["O","4x50 DESKA P/K",200],["V","4x50 PV 1-3 1-1-1",200],["V","8x25 PR DN",200],["V","6x25 PPV",150],["G","4x50 P @1'15\"",200],["M","50 RAZP",50],["Z","8x25 1x MAX 1x RAZP",200],["K","50 RAZP",50]]},{"d":"2026-11-04","l":"A","o":0,"m":2250,"e":32,"i":[["R","300 RAZP",300],["O","25 D + 50 H + 75 P + 100 K CT",250],["V","25 DV + 50 HV + 75 PV + 100 KV",250],["V","8x25 PL ↑MAX N ↓RAZP",200],["V","4x50 PL ↑DN PR ↓DV 1-1-2",200],["M","50 RAZP",50],["G","4x50 3+1 @1'\n4x75 STOP PO 25 @1'30\"\n4x100 1x K 1x M @2'",900],["K","100 RAZP",100]]},{"d":"2026-11-09","l":"AB","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","8x50 M 4xV 4xCT",400],["V","4x50 PL KV @1'10\"",200],["V","4x50 PL KV RRU SHARK",200],["G","4x50 K 3+1 @1'\n4x50 K 1-4 @1'\n4x50 K VL @50\"\n4x50 KN @1'20\"\n4x50 ↑KBD ↓RAZP p30\"",1000],["Z","4x50 K/H NA DOLGO",200]]},{"d":"2026-11-12","l":"AB","o":0,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","4x75 MM 25+50",300],["V","10x25 PL ↑K MAX FREK ↓H",250],["V","4x50 PL K RRU PPDZ",200],["M","50 RAZP",50],["G","3x( 4x100 @2' ) 1x VL 1x 75 K + 25 N 1x NORMALNO",1200],["K","100 RAZP",100]]},{"d":"2026-11-11","l":"C","o":0,"m":1650,"e":33,"i":[["R","200 RAZP",200],["O","6x50 ↑PD 5s ↓H/K",300],["O","25 K + 50 H + 75 P + 100 P 1-2 + 75 P 1-2 + 50 H + 25 K",400],["M","50 RAZP",50],["V","10x25 PL K/H N",250],["V","4x50 PL KV 2-2",200],["V","4x50 PL K RRU PALEC",200],["K","50 RAZP",50]]},{"d":"2026-11-11","l":"A","o":0,"m":2350,"e":33,"i":[["R","300 RAZP",300],["O","8x50 MM",400],["V","8x25 PL ↑DN H ↓DN PV",200],["V","4x50 K RRU ŠPRICANJE/PALEC",200],["M","50 RAZP",50],["G","4x100 KVL @2'\n4x75 MBK @1'30\"\n4x50 K @50\"\n4x50 25! + 25 @1'",1100],["K","100 RAZP",100]]},{"d":"2026-11-16","l":"AB","o":1,"m":2400,"e":34,"i":[["R","300 RAZP",300],["O","16x25 M PO 4 ↑N ↓CT",400],["G","3x( 150 VL @3' / 100 T @2' / 50 HITRO @1' / 25 D + 25 RAZP )",1050],["M","50 RAZP",50],["V","10x25 PL K VISOK KOMOLEC",250],["V","6x50 PL KZ 1x NORMALNO 1x DIH KONTRA",300],["K","50 RAZP",50]]},{"d":"2026-11-19","l":"AB","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","4x75 M VB1T",300],["V","4x50 PL ↑K ↓KBD",200],["V","8x25 ↑D DIH NA 1 ↓DV 3-3",200],["V","6x25 PL ↑D MAX ↓RAZP",150],["M","50 RAZP",50],["G","4x25 KBD p15\"\n4x50 25 D + 25 K @1'\n4x75 50 K + 25 D @1'30\"\n4x100 KVL @2'",1000],["K","100 RAZP",100]]},{"d":"2026-11-18","l":"A","o":0,"m":2300,"e":33,"i":[["R","300 RAZP",300],["O","4x100 M PO 100 25 V + 50 N + 25 CT",400],["V","4x75 PL D 7-5-3",300],["V","4x50 PL DV 1x 3-3 1x 2-2-1 DIH NAPREJ",200],["M","50 RAZP",50],["G","6x25 1x KBD 1x H p15\"\n6x50 KVL @1'\n6x25 1x D 1x H p15\"\n6x50 2+1 @1'",900],["K","150 RAZP",150]]}]$j$::jsonb) x;

  IF EXISTS (SELECT 1 FROM _t JOIN public.trainings t ON t.trainer_id = o AND t.date = _t.d AND t.levels = _t.lv) THEN
    RAISE EXCEPTION 'Kateri od treningov je že v bazi';
  END IF;

  CREATE TEMP TABLE _i ON COMMIT DROP AS
  SELECT _t.d, _t.lv, (i.ord - 1)::int AS pos,
         CASE i.v->>0 WHEN 'R' THEN 'razplavanje' WHEN 'O' THEN 'ogrevalna' WHEN 'V' THEN 'vaje' WHEN 'M' THEN 'vmesno_razplavanje'
                      WHEN 'G' THEN 'glavna' WHEN 'Z' THEN 'zakljucek' WHEN 'K' THEN 'zakljucno_razplavanje' END AS phase,
         i.v->>1 AS txt, (i.v->>2)::int AS m,
         coalesce(i.v->>3, replace(replace(upper(i.v->>1), '( ', '('), ' )', ')')) AS fp, i.v->>4 AS main_type
  FROM _t CROSS JOIN LATERAL jsonb_array_elements(_t.items) WITH ORDINALITY AS i(v, ord);

  -- Serije; če serija že obstaja, se ji samo dodajo nivoji.
  INSERT INTO public.training_sets AS ts (trainer_id, phase, levels, text, structure, meters, fingerprint, main_type, source, notes)
  SELECT o, phase, (SELECT array_agg(DISTINCT u ORDER BY u) FROM _i j, unnest(j.lv) u WHERE j.phase = i.phase AND j.fp = i.fp),
         min(txt), jsonb_build_object('v', 1, 'meters', min(m)), min(m), fp, min(main_type), 'uvoz', 'zvezek 2026'
  FROM _i i WHERE phase IN ('ogrevalna', 'vaje', 'glavna', 'zakljucek') GROUP BY phase, fp
  ON CONFLICT (trainer_id, phase, fingerprint) DO UPDATE
    SET levels = (SELECT array_agg(DISTINCT u ORDER BY u) FROM unnest(ts.levels || excluded.levels) u);
  GET DIAGNOSTICS k = ROW_COUNT;
  IF k <> 177 THEN RAISE EXCEPTION 'Serije: %', k; END IF;

  INSERT INTO public.trainings (trainer_id, term_id, date, levels, status, order_variant, total_meters, estimated_minutes, notes)
  SELECT o, (SELECT te.id FROM public.terms te JOIN public.trainer_terms tt ON tt.term_id = te.id
              WHERE tt.trainer_id = o AND te.day = extract(isodow FROM _t.d)::int
                AND _t.d BETWEEN coalesce(te.date_from, _t.d) AND coalesce(te.date_to, _t.d) LIMIT 1),
         _t.d, _t.lv, 'izveden', _t.ord, _t.m, _t.e, note
  FROM _t;

  INSERT INTO public.training_items (training_id, position, phase, set_id, text, structure, meters, fingerprint, level_variants)
  SELECT t.id, i.pos, i.phase,
         (SELECT x.id FROM public.training_sets x WHERE x.trainer_id = o AND x.phase = i.phase AND x.fingerprint = i.fp),
         i.txt, jsonb_build_object('v', 1, 'meters', i.m), i.m, i.fp, '{}'::jsonb
  FROM _i i JOIN public.trainings t ON t.trainer_id = o AND t.date = i.d AND t.levels = i.lv AND t.notes = note;

  SELECT count(DISTINCT t.id), count(i.id), sum(i.meters), count(i.set_id) INTO n, k, s, l
  FROM public.trainings t JOIN public.training_items i ON i.training_id = t.id WHERE t.trainer_id = o AND t.notes = note;
  IF n <> 39 OR k <> 304 OR s <> 81700 OR l <> 184 THEN
    RAISE EXCEPTION 'Kontrola: treningov %, postavk %, metrov %, povezanih %', n, k, s, l;
  END IF;
  IF EXISTS (SELECT 1 FROM public.trainings t WHERE t.trainer_id = o AND t.notes = note
             AND (t.term_id IS NULL OR t.total_meters <> (SELECT sum(i.meters) FROM public.training_items i WHERE i.training_id = t.id))) THEN
    RAISE EXCEPTION 'Trening brez termina ali z napačno vsoto';
  END IF;
END $do$;
